def build(prefix, count, n, out):
    if len(prefix) == n:
        out.append(prefix)
        return
    for ch in sorted(count):
        if count[ch] > 0:
            count[ch] -= 1
            build(prefix + ch, count, n, out)
            count[ch] += 1

