frontier = []
healthy = 0
for i in range(r):
    for j in range(c):
        if g[i][j] == 2:
            frontier.append((i, j))
        elif g[i][j] == 1:
            healthy += 1
minutes = 0
while frontier and healthy > 0:
    nxt = []
    for i, j in frontier:
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            x, y = i + di, j + dj
            if 0 <= x < r and 0 <= y < c and g[x][y] == 1:
                g[x][y] = 2
                healthy -= 1
                nxt.append((x, y))
    frontier = nxt
    minutes += 1
print(minutes if healthy == 0 else -1)
